operations.body:
query GetComicProject {
  comicPages(first: 100) {
    nodes {
      id
      comicPageFields {
        project
        order
        titleEs
        titleEn
        descriptionEs
        descriptionEn
        image {
          node {
            sourceUrl
            altText
            caption
            title
            imageTranslations {
              altEn
              captionEn
              titleEn
              __typename
            }
            mediaDetails {
              width
              height
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

query GetComicProjects {
  comicProjects(where: {orderby: {field: DATE, order: ASC}}) {
    nodes {
      id
      title
      comicProjectFields {
        titleEs
        titleEn
        descriptionEs
        descriptionEn
        displayType
        coverImage {
          node {
            sourceUrl
            altText
            caption
            title
            imageTranslations {
              altEn
              captionEn
              titleEn
              __typename
            }
            __typename
          }
          __typename
        }
        slug
        ctaEs
        ctaEn
        __typename
      }
      __typename
    }
    __typename
  }
}

query GetEvents {
  events {
    nodes {
      id
      title
      excerpt
      featuredImage {
        node {
          sourceUrl
          altText
          __typename
        }
        __typename
      }
      eventFields {
        eventDate
        eventTime
        location
        externalLink
        __typename
      }
      __typename
    }
    __typename
  }
}

query GetGallery {
  mediaItems(first: 100) {
    nodes {
      id
      sourceUrl
      altText
      caption
      title
      imageTranslations {
        altEn
        captionEn
        titleEn
        __typename
      }
      mediaDetails {
        width
        height
        sizes {
          name
          sourceUrl
          __typename
        }
        __typename
      }
      attachmentCategories
      __typename
    }
    __typename
  }
}

query GetHomeGallery {
  homeGalleryImages(where: {orderby: {field: DATE, order: ASC}}) {
    nodes {
      featuredImage {
        node {
          sourceUrl
          altText
          caption
          databaseId
          imageTranslations {
            altEn
            captionEn
            titleEn
            __typename
          }
          mediaDetails {
            width
            height
            sizes {
              name
              sourceUrl
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

query GetPageById($id: ID!) {
  page(id: $id, idType: DATABASE_ID) {
    pageFields {
      titleEs
      titleEn
      descriptionEs
      descriptionEn
      __typename
    }
    __typename
  }
}

query GetPageByUri($slug: String!) {
  pageBy(uri: $slug) {
    pageFields {
      titleEs
      titleEn
      descriptionEs
      descriptionEn
      __typename
    }
    __typename
  }
}

query GetPost($slug: ID!) {
  post(id: $slug, idType: SLUG) {
    title
    date
    content
    featuredImage {
      node {
        sourceUrl
        altText
        __typename
      }
      __typename
    }
    categories {
      nodes {
        name
        slug
        __typename
      }
      __typename
    }
    postTranslations {
      linkedPostEn {
        nodes {
          ... on Post {
            slug
            __typename
          }
          __typename
        }
        __typename
      }
      linkedPostEs {
        nodes {
          ... on Post {
            slug
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

query GetPosts {
  posts(first: 100) {
    nodes {
      title
      slug
      excerpt
      date
      featuredImage {
        node {
          sourceUrl
          altText
          caption
          title
          imageTranslations {
            altEn
            captionEn
            titleEn
            __typename
          }
          mediaDetails {
            sizes {
              name
              sourceUrl
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      categories {
        nodes {
          name
          slug
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
